### Iteration 5: 1D Grid without Shared Memory
This kernel uses a 1D grid layout and avoids shared memory to reduce memory usage while maintaining coalesced memory access.

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel source code with 1D grid and no shared memory
cuda_source = """
#include <torch/extension.h>

__global__ void matrix_mult_kernel(const float* A, const float* B, float* C, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_threads = gridDim.x * blockDim.x;

    for (int i = idx; i < N * N; i += total_threads) {
        int row = i / N;
        int col = i % N;

        float sum = 0.0f;
        for (int k = 0; k < N; k++) {
            sum += A[row * N + k] * B[k * N + col];
        }
        C[i] = sum;
    }
}

torch::Tensor matrix_mult_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    // Thread block and grid dimensions
    int block_size = 256;
    int grid_size = (N * N + block_size - 1) / block_size;

    matrix_mult_kernel<<<grid_size, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

